      { question: "Why did the first civilizations develop along rivers?", answer: "Rivers provided water, fertile soil, food, and transportation — enabling farming that freed people for other work", options: ["Rivers provided gold and treasure", "Rivers provided water, fertile soil, food, and transportation — enabling farming that freed people for other work", "People liked swimming", "Rivers had no importance — it was coincidence"] },
      { question: "Why are these ancient inventions still important?", answer: "Writing, math, law, calendars, and the wheel are foundations of modern civilization that we use every day", options: ["They are not important anymore", "Writing, math, law, calendars, and the wheel are foundations of modern civilization that we use every day", "Only historians care about them", "They were replaced by better inventions"] }
